const r = await tools.exec_command({
  cmd: "python - <<'PY'
import os,re,json,csv
from collections import defaultdict,deque
base='/app'

def parse_items(path,kind):
    fn=os.path.basename(path)
    txt=open(path).read()
    out={}
    if fn.endswith('.json'):
        d=json.loads(txt)
        for x in d['items']:
            p=x['prod_id']; q=x['qty' if kind=='order' else 'delivered_qty']; out[p]=int(q)
    elif fn.endswith('.csv'):
        ls=txt.strip().splitlines()[1:]
        for l in ls:
            p,q=l.split(';'); out[p]=int(q)
    elif 'key-value' in fn:
        pat=(r'ORDER_PRODUCT: (P_\d+) \| ORDER_QTY: (\d+)' if kind=='order' else r'PRODUCT: (P_\d+) \| DELIVERED_QTY: (\d+)')
        out={p:int(q) for p,q in re.findall(pat,txt)}
    else:
        pat=(r'deliver (\d+) units of product (P_\d+)' if kind=='order' else r'delivered (\d+) units of product (P_\d+)')
        for q,p in re.findall(pat,txt): out[p]=int(q)
    return out

orders={}
for fn in os.listdir(base+'/raw_orders'):
    m=re.match(r'day_(\d+)_S_(\d+)_',fn); d,s=map(int,m.groups())
    orders[d,s]=parse_items(base+'/raw_orders/'+fn,'order')
supp={}
for fn in os.listdir(base+'/raw_supplier_receipts'):
    m=re.match(r'day_(\d+)_PR_(\d+)_',fn); d,pr=map(int,m.groups())
    supp[d,pr]=parse_items(base+'/raw_supplier_receipts/'+fn,'supp')
seqp={}
for fn in os.listdir(base+'/raw_wholesaler_receipts'):
    txt=open(base+'/raw_wholesaler_receipts/'+fn).read()
    d=int(re.search(r'DAY: (\d+)',txt).group(1)); pr=int(re.search(r'SUPPLIER_ID: PR_(\d+)',txt).group(1)); sq=int(re.search(r'DAILY_SEQUENCE_NO: (\d+)',txt).group(1))
    seqp[d,pr]=sq
seqs={}; totals={}
for fn in os.listdir(base+'/raw_wholesaler_store_receipts'):
    txt=open(base+'/raw_wholesaler_store_receipts/'+fn).read()
    d=int(re.search(r'DAY: (\d+)',txt).group(1)); s=int(re.search(r'STORE_ID: S_(\d+)',txt).group(1)); sq=int(re.search(r'DAILY_SEQUENCE_NO: (\d+)',txt).group(1)); total=int(re.search(r'TOTAL_DELIVERED_UNITS: (\d+)',txt).group(1))
    seqs[d,s]=sq; totals[d,s]=total
print('parsed',len(orders),len(supp),len(seqp),len(seqs))
print('order days counts', {x:sum(1 for d,s in orders if d==x) for x in [1,2,3,4,5,100,365]})
# Simulate arrivals then allocation, wholesale FIFO producer batches by product
wh=defaultdict(deque); mism=[]; delivered_by={}
for d in range(1,366):
  for pr in sorted(range(1,61), key=lambda pr:seqp[d,pr]):
    for p,q in supp[d,pr].items(): wh[p].append([q,pr,d])
  for s in sorted(range(1,11),key=lambda s:seqs[d,s]):
    got=0
    if (d,s) in orders:
      for p,q in orders[d,s].items():
        need=q; take=0
        while need and wh[p]:
          n=min(need,wh[p][0][0]); need-=n; take+=n; wh[p][0][0]-=n
          if wh[p][0][0]==0: wh[p].popleft()
        got+=take
    if got!=totals[d,s]: mism.append((d,s,got,totals[d,s]))
print('allocation mismatches',len(mism),mism[:20])
print('remaining wholesale',sum(x[0] for dq in wh.values() for x in dq))
PY",
  workdir: "/app",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);

